typedef unsigned int u_int;

extern float WAVE_MeshMinX;
extern float WAVE_MeshMaxX;
extern float WAVE_MeshMinZ;
extern float WAVE_MeshMaxZ;
extern float WATER_MeshGridX[12];
extern float WATER_MeshGridZ[12];
extern float WATER_MeshGridU[12];
extern float WATER_MeshGridV[12];
extern u_int WATER_MeshStepX;
extern u_int WATER_MeshStepZ;
extern float WATER_MeshMinX;
extern float WATER_MeshMaxX;
extern float WATER_MeshMinZ;
extern float WATER_MeshMaxZ;
extern float WATER_SeamSizeX;
extern float WATER_SeamSizeZ;
extern float WATER_ScaleU;
extern float WATER_ScaleV;
extern float WATER_OffsetU;
extern float WATER_OffsetV;

__asm__(".equ WATER_ScaleU, 0x004845BC");
__asm__(".equ WATER_ScaleV, 0x004845C0");
__asm__(".equ WATER_OffsetU, 0x004845C4");
__asm__(".equ WATER_OffsetV, 0x004845C8");
__asm__(".equ WATER_MeshMinX, 0x004845D0");
__asm__(".equ WATER_MeshMaxX, 0x004845D4");
__asm__(".equ WATER_MeshMinZ, 0x004845D8");
__asm__(".equ WATER_MeshMaxZ, 0x004845DC");
__asm__(".equ WAVE_MeshMinX, 0x00484620");
__asm__(".equ WAVE_MeshMaxX, 0x00484624");
__asm__(".equ WAVE_MeshMinZ, 0x00484628");
__asm__(".equ WAVE_MeshMaxZ, 0x0048462C");
__asm__(".equ WATER_MeshGridX, 0x0057E950");
__asm__(".equ WATER_MeshGridZ, 0x0057E980");
__asm__(".equ WATER_MeshGridU, 0x0057E9B0");
__asm__(".equ WATER_MeshGridV, 0x0057E9E0");
__asm__(".equ WATER_MeshStepX, 0x0057EA10");
__asm__(".equ WATER_MeshStepZ, 0x0057EA14");
__asm__(".equ WATER_SeamSizeX, 0x0057EA18");
__asm__(".equ WATER_SeamSizeZ, 0x0057EA1C");

#define WATER_MESHIDEALSTEPX 8
#define WATER_MESHIDEALSTEPZ 8
#define WATER_MESH_WIDTH (WATER_MeshMaxX - WATER_MeshMinX)
#define WATER_MESH_DEPTH (WATER_MeshMaxZ - WATER_MeshMinZ)

static inline void WATER_TextureCoordU(float x, float &u)
{
	u = WATER_ScaleU * x + WATER_OffsetU;
}

static inline void WATER_TextureCoordV(float z, float &v)
{
	v = WATER_ScaleV * z + WATER_OffsetV;
}

static void WATER_ComputeUniformGrid(void)
{
	u_int xstep, zstep;
	float xbase, zbase;
	const float xcutlo = WAVE_MeshMinX - WATER_SeamSizeX;
	const float xcuthi = WAVE_MeshMaxX + WATER_SeamSizeX;
	const float zcutlo = WAVE_MeshMinZ - WATER_SeamSizeZ;
	const float zcuthi = WAVE_MeshMaxZ + WATER_SeamSizeZ;

	if (WATER_MeshMinX > xcutlo)
	{
		WATER_MeshMinX = xcutlo;
	}
	if (WATER_MeshMaxX < xcuthi)
	{
		WATER_MeshMaxX = xcuthi;
	}
	if (WATER_MeshMinZ > zcutlo)
	{
		WATER_MeshMinZ = zcutlo;
	}
	if (WATER_MeshMaxZ < zcuthi)
	{
		WATER_MeshMaxZ = zcuthi;
	}

	float xinc = ((float) WATER_MESH_WIDTH) / WATER_MESHIDEALSTEPX;
	float zinc = ((float) WATER_MESH_DEPTH) / WATER_MESHIDEALSTEPZ;

	for (xstep = 0, xbase = WATER_MeshMinX; xstep <= WATER_MESHIDEALSTEPX; ++xstep, xbase += xinc)
	{
		WATER_MeshGridX[xstep] = xbase;
		WATER_TextureCoordU(WATER_MeshGridX[xstep], WATER_MeshGridU[xstep]);
	}
	WATER_MeshStepX = WATER_MESHIDEALSTEPX;

	for (zstep = 0, zbase = WATER_MeshMinZ; zstep <= WATER_MESHIDEALSTEPZ; ++zstep, zbase += zinc)
	{
		WATER_MeshGridZ[zstep] = zbase;
		WATER_TextureCoordV(WATER_MeshGridZ[zstep], WATER_MeshGridV[zstep]);
	}
	WATER_MeshStepZ = WATER_MESHIDEALSTEPZ;
}
